from collections import deque

def run_stack_ops(ops):
    q = deque()
    output = []

    for op, arg in ops:
        if op == 'push':
            q.append(arg)
            for _ in range(len(q) - 1):
                q.append(q.popleft())
        elif op == 'pop':
            output.append(q.popleft())
        elif op == 'top':
            output.append(q[0])
        elif op == 'empty':
            output.append(len(q) == 0)

    return output

